@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_command_output_is_packet_79(version):
    assert version.packets[79] is version.CommandOutputPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_command_output_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_command_output_decodes_from_its_golden(packet, golden):
    assert v2225.CommandOutputPacket.from_bytes(golden) == packet


def test_command_output_name_codes_read_case_insensitively():
    assert v2225.CommandOutputPacket.from_bytes(BINDING_CASING) == FILLED
